\set ON_ERROR_STOP on
begin;
with d as (select id, insurance_company_id from program_document where id::text like '93b76c4c%')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl from d cross join (values
('общие-исключения','иммобилизационные системы','excluded','кроме гипсовых и полимерных повязок при травме в срок действия договора','п. 11.23.2.25'),
('общие-условия','услуги вне территории программы','excluded','кроме услуг при организованной Страховщиком поездке на лечение и обратно','п. 11.23.2.26'),
('общие-условия','очный приём по телемедицинской программе','excluded','для программ с телемедициной очные посещения не оплачиваются','п. 11.23.2.27'),
('общие-условия','услуги сверх лимитов программы по числу кратности стоимости','excluded','превышение лимитов Программы (число, кратность, страховая сумма) не оплачивается','п. 11.23.2.28'),
('общие-условия','программа укус клеща лечение иных заболеваний','excluded','по клещевым программам не оплачивается лечение заболеваний, не связанных с укусом клеща','п. 11.23.3.1'),
('общие-условия','программа укус клеща заболевания до начала страхования','excluded','включая укус, произошедший до начала действия страхования','п. 11.23.3.2'),
('общие-условия','программа укус клеща услуги и лекарства вне программы на дому скорая','excluded','а также услуги лицу, не являющемуся Застрахованным','п. 11.23.4.1 – 11.23.4.2'),
('общие-условия','программа укус клеща услуги до начала или после окончания страхования','excluded','кроме продолжения начатого в срок договора стационарного лечения','п. 11.23.4.3')
) as v(sc, sp, vd, ct, cl);
commit;
